      </p>{/if}
    {#if details.summary.currencies.length === 0}<p class="empty-details">
        {details.summary.entryCount === 0
          ? "No funding entries are stored for this MP."
          : "No known currencies are available for totals."}
      </p>{/if}
    <div class="member-currency-totals">
      {#each details.summary.currencies as group}<div>
          <h3>{group.currency}</h3>
          <p class="member-total">{formatAmount(group.amount)}</p>
          <p class="entry-count">
            {group.entryCount} funding {group.entryCount === 1
              ? "entry"
              : "entries"}{#if group.unknownAmountCount}, {group.unknownAmountCount}
              amounts unavailable{/if}
          </p>
        </div>{/each}
    </div>
    {#if details.summary.undatedDeclarationCount && !details.summary.firstRegisteredAt}<p
        class="stored-coverage"
      >
        Registration dates are unavailable.
      </p>{/if}
    {#if details.summary.unknownCurrencyCount}<p class="coverage-note">
        {details.summary.unknownCurrencyCount} funding {details.summary
          .unknownCurrencyCount === 1
          ? "entry has"
          : "entries have"} an unknown currency and are excluded from monetary totals.
      </p>{/if}
  </section>
  <section class="member-breakdown" aria-labelledby="breakdown-heading">
    <h2 id="breakdown-heading">Declared value by category</h2>
    <p class="summary-context">
      Amounts recorded in each category, with currencies kept separate.
    </p>
    {#each details.summary.currencies as group}
      {@const bars = categoryBars(group.categories)}
      {@const signed = bars.some((bar) => bar.negative)}
      <div class="category-currency">
        <h3>{group.currency}</h3>
        <ul class="category-list">
          {#each group.categories as category, index}<li>
              <div class="category-label">
                <span>{category.categoryName}</span><span class="amount"
                  >{formatAmount(category.amount)} {group.currency}</span
                >
              </div>
              <div class="signed-bar" class:signed aria-hidden="true">
                <span
                  class:negative={bars[index].negative}
                  style:width={`${bars[index].width / (signed ? 2 : 1)}%`}
                ></span>
              </div>
              {#if category.unknownAmountCount}<p class="partial-note">
                  {category.unknownAmountCount} amounts unavailable
                </p>{/if}
            </li>{/each}
        </ul>
      </div>
    {/each}
  </section>
</div>
<section aria-labelledby="support-heading">
  <div class="detail-section-heading">
    <h2 id="support-heading">Recent donations and support</h2>
    <p>
      Latest declared support, including loans. Support may be received by the
      MP or a party organisation.
    </p>
  </div>
  {#if details.recentSupport.length}<MemberDeclarations
      declarations={details.recentSupport}
      showCategory={false}
    />{:else}<p class="empty-details">
      No donations or support declarations are stored for this MP.
    </p>{/if}
  <a
    class="text-button history-link"
    href={memberHref(details.member.id, "history")}
    >View all {details.declarations.length} declarations</a
  >
</section>
export type DetailRoute =
  | { kind: "search" }
  | { kind: "member"; id: string; view: "summary" | "history" }
  | { kind: "funder"; id: string }
  | { kind: "invalid" };

const funderIdPattern =
  /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu;
const memberIdPattern = /^[1-9]\d*$/u;

export function readDetailRoute(path: string): DetailRoute {
  if (path === "/") return { kind: "search" };
  const member = /^\/members\/([^/]+)(?:\/(history))?\/?$/u.exec(path);
  if (
    member &&
    memberIdPattern.test(member[1]) &&
    Number(member[1]) <= 2147483647
  )
    return {
      kind: "member",
      id: member[1],
      view: member[2] ? "history" : "summary",
    };
  const funder = /^\/funders\/([^/]+)\/?$/u.exec(path);
  if (funder && funderIdPattern.test(funder[1]))
    return { kind: "funder", id: funder[1] };
  return { kind: "invalid" };
}

export interface MemberProfile {
  id: string;
  name: string;
  partyName: string;
  membershipFrom: string;
  isCurrentCommons: boolean;
}

export interface FundingEntry {
  funder: { id: string; name: string } | null;
  amount: string | null;
  currency: string | null;
  paymentType: string | null;
}

export interface MemberDeclaration {
  sourceId: number;
  categoryId: number;
  categoryName: string;
  registeredAt: string | null;
  entries: FundingEntry[];
}

export interface MemberDetails {
  member: MemberProfile;
  declarations: MemberDeclaration[];
  recentSupport: MemberDeclaration[];
  summary: {
    currencies: (Total & {
      currency: string;
      categories: (Total & { categoryId: number; categoryName: string })[];
    })[];
    entryCount: number;
    unknownCurrencyCount: number;
    firstRegisteredAt: string | null;
    lastRegisteredAt: string | null;
    undatedDeclarationCount: number;
  };
}

interface Total {
  amount: string | null;
  entryCount: number;
  unknownAmountCount: number;
}

export interface FunderDetails {
  funder: {
    id: string;
    name: string;
    funderKind: string | null;
    companyNumber: string | null;
    aliases: string[];
  };
  currencies: {
    currency: string;
    parties: (Total & { partyName: string })[];
    topRecipients: (Total & { member: MemberProfile })[];
  }[];
  entryCount: number;
  unknownCurrencyCount: number;
  recipientLimit: number;
}

export type DetailState =
  | { kind: "loading" }
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
  | { kind: "error"; message: string };

function malformed(): never {
  throw new Error("Details returned an unexpected response. Try again.");
}
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function record(value: unknown): Record<string, unknown> {
  return isRecord(value) ? value : malformed();
}
function text(value: unknown): string {
  return typeof value === "string" ? value : malformed();
}
function nullableText(value: unknown): string | null {
  return value === null ? null : text(value);
}
function count(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : malformed();
}
function list(value: unknown): unknown[] {
  return Array.isArray(value) ? value : malformed();
}
function decimal(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !/^-?\d+(?:\.\d+)?$/u.test(result)) return malformed();
  return result;
}
function identity(value: unknown, kind: "MP" | "Funder"): string {
  const id = text(value);
  if (
    kind === "MP"
      ? !memberIdPattern.test(id) || Number(id) > 2147483647
      : !funderIdPattern.test(id)
  )
    return malformed();
  return id;
}
function memberProfile(value: unknown): MemberProfile {
  const row = record(value);
  if (typeof row.is_current_commons !== "boolean") return malformed();
  return {
    id: identity(row.id, "MP"),
    name: text(row.name),
    partyName: text(row.party_name),
    membershipFrom: text(row.membership_from),
    isCurrentCommons: row.is_current_commons,
  };
}
function integer(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value)
    ? value
    : malformed();
}
function timestamp(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !Number.isFinite(Date.parse(result)))
    return malformed();
  return result;
}
function declaration(value: unknown): MemberDeclaration {
  const row = record(value);
  return {
    sourceId: count(row.source_id),
    categoryId: integer(row.category_id),
    categoryName: text(row.category_name),
    registeredAt: timestamp(row.registered_at),
    entries: list(row.entries).map((value) => {
      const entry = record(value);
      const funder = entry.funder === null ? null : record(entry.funder);
      return {
        funder:
          funder === null
            ? null
            : { id: identity(funder.id, "Funder"), name: text(funder.name) },
        amount: decimal(entry.amount),
        currency: nullableText(entry.currency),
        paymentType: nullableText(entry.payment_type),
      };
    }),
  };
}
function readMember(value: unknown): MemberDetails {
  const row = record(value);
  const summary = record(row.summary);
  return {
    member: memberProfile(row.member),
    declarations: list(row.declarations).map(declaration),
    recentSupport: list(row.recent_support).map(declaration),
    summary: {
      entryCount: count(summary.entry_count),
      unknownCurrencyCount: count(summary.unknown_currency_count),
      firstRegisteredAt: timestamp(summary.first_registered_at),
      lastRegisteredAt: timestamp(summary.last_registered_at),
      undatedDeclarationCount: count(summary.undated_declaration_count),
      currencies: list(summary.currencies).map((value) => {
        const group = record(value);
        const currency = text(group.currency);
        if (!currency.trim()) return malformed();
        return {
          ...total(group),
          currency,
          categories: list(group.categories).map((value) => {
            const category = record(value);
            return {
              ...total(category),
              categoryId: integer(category.category_id),
              categoryName: text(category.category_name),
            };
          }),
        };
      }),
    },
  };
}
function total(row: Record<string, unknown>): Total {
  return {
    amount: decimal(row.amount),
    entryCount: count(row.entry_count),
    unknownAmountCount: count(row.unknown_amount_count),
  };
}
function readFunder(value: unknown): FunderDetails {
  const row = record(value);
  const funder = record(row.funder);
  return {
    funder: {
      id: identity(funder.id, "Funder"),
      name: text(funder.name),
      funderKind: nullableText(funder.funder_kind),
      companyNumber: nullableText(funder.company_number),
      aliases: list(funder.aliases).map(text),
    },
    entryCount: count(row.entry_count),
    unknownCurrencyCount: count(row.unknown_currency_count),
    recipientLimit: count(row.recipient_limit),
    currencies: list(row.currencies).map((value) => {
      const group = record(value);
      const currency = text(group.currency);
      if (!currency.trim()) return malformed();
      return {
        currency,
        parties: list(group.parties).map((value) => {
          const party = record(value);
          return { ...total(party), partyName: text(party.party_name) };
        }),
        topRecipients: list(group.top_recipients).map((value) => {
          const recipient = record(value);
          return {
            ...total(recipient),
            member: memberProfile(recipient.member),
          };
        }),
      };
    }),
  };
}

export async function loadDetails(
  route: Extract<DetailRoute, { kind: "member" | "funder" }>,
  signal: AbortSignal,
): Promise<DetailState> {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, 10_000);
  try {
    const response = await fetch(
      `/api/${route.kind === "member" ? "members" : "funders"}/${route.id}`,
      { signal: controller.signal },
    );
    if (response.status === 404) return { kind: "not-found" };
    if (!response.ok)
      throw new Error(
        "The details service is unavailable. Try again in a moment.",
      );
    const body: unknown = await response.json();
    const state: DetailState =
      route.kind === "member"
        ? { kind: "member", details: readMember(body) }
        : { kind: "funder", details: readFunder(body) };
    if (
      (state.kind === "member"
        ? state.details.member.id
        : state.details.funder.id
      ).toLowerCase() !== route.id.toLowerCase()
    )
      return malformed();
    return state;
  } catch (error) {
    if (signal.aborted) throw error;
    return {
      kind: "error",
      message: timedOut
        ? "Details are taking too long. Try again."
        : error instanceof Error &&
            !(error instanceof TypeError || error instanceof SyntaxError)
          ? error.message
          : "Couldn’t connect to details. Check your connection and try again.",
    };
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", cancel);
  }
}

export function backToSearch(): string {
  const params = new URLSearchParams(window.location.search);
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  return retained.size ? `/?${retained}` : "/";
}

export function formatAmount(value: string | null): string {
  if (value === null) return "Amount unavailable";
  const negative = value.startsWith("-");
  const unsigned = negative ? value.slice(1) : value;
  const [whole, fraction] = unsigned.split(".");
  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
}

export function registrationDate(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}

export function memberHref(id: string, view: "summary" | "history"): string {
  const search = backToSearch().slice(1);
  return `/members/${id}${view === "history" ? "/history" : ""}${search}`;
}

export function categoryBars(
  categories: { amount: string | null }[],
): { width: number; negative: boolean }[] {
  const scale = Math.max(
    0,
    ...categories.map(({ amount }) => amount?.split(".")[1]?.length ?? 0),
  );
  const values = categories.map(({ amount }) => {
    if (amount === null) return 0n;
    const [whole, fraction = ""] = amount.replace(/^-/, "").split(".");
    const value = BigInt(whole + fraction.padEnd(scale, "0"));
    return amount.startsWith("-") ? -value : value;
  });
  const maximum = values.reduce((largest, value) => {
    const magnitude = value < 0n ? -value : value;
    return magnitude > largest ? magnitude : largest;
  }, 0n);
  return values.map((value) => ({
    negative: value < 0n,
    width:
      maximum === 0n
        ? 0
        : Number(((value < 0n ? -value : value) * 10000n) / maximum) / 100,
  }));
}

